begin;
select plan(8);
insert into auth.users(id,email) values ('b0000000-0000-0000-0000-000000000001','stock-admin@example.test'),('b0000000-0000-0000-0000-000000000002','stock-worker@example.test');
insert into public.profiles(id,display_name,role,active) values ('b0000000-0000-0000-0000-000000000001','Admin','admin',true),('b0000000-0000-0000-0000-000000000002','Worker','collaborator',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','b0000000-0000-0000-0000-000000000001',true);
select public.create_material('Finished test','g',0);
select public.adjust_warehouse_stock('b0000000-0000-0000-0000-000000000003',(select id from public.materials where name='Finished test'),10,'initial');
select public.dispatch_stock('b0000000-0000-0000-0000-000000000004','b0000000-0000-0000-0000-000000000002',(select id from public.materials where name='Finished test'),10,'');
select public.save_product(null,'Finished product','','','',10,true);
select public.save_customer(null,'Finished customer','',true);
select public.create_recipe((select id from public.products where name='Finished product'),jsonb_build_array(jsonb_build_object('material',(select id from public.materials where name='Finished test'),'quantity',1)));
select public.create_production_assignment('b0000000-0000-0000-0000-000000000005','b0000000-0000-0000-0000-000000000002',(select id from public.products where name='Finished product'),2,1,null,'');
select public.create_sales_order('b0000000-0000-0000-0000-000000000006',(select id from public.customers where name='Finished customer'),(select id from public.products where name='Finished product'),'2026-01-01',null,2,10,'');
select set_config('request.jwt.claim.sub','b0000000-0000-0000-0000-000000000002',true);
select public.confirm_stock_receipt((select id from public.stock_transfers));
select public.record_production('b0000000-0000-0000-0000-000000000007',(select id from public.production_assignments),'2026-01-01',2,'');
select throws_ok($$select public.deliver_order('b0000000-0000-0000-0000-000000000008','b0000000-0000-0000-0000-000000000006','2026-01-01',1,'')$$,'42501','access denied','worker cannot deliver');
select set_config('request.jwt.claim.sub','b0000000-0000-0000-0000-000000000001',true);
select public.receive_finished_production('b0000000-0000-0000-0000-000000000009',(select id from public.production_assignments),'2026-01-01',1,'');
select lives_ok($$select public.deliver_order('b0000000-0000-0000-0000-000000000008',(select id from public.sales_orders),'2026-01-01',1,'')$$,'admin delivers available stock');
select lives_ok($$select public.deliver_order('b0000000-0000-0000-0000-000000000008',(select id from public.sales_orders),'2026-01-01',1,'')$$,'retry does not duplicate');
select is((select delivered from public.order_delivery_progress),1::bigint,'one unit delivered');
select is((select received-delivered from public.finished_stock),0::bigint,'available stock consumed once');
select throws_ok($$select public.deliver_order('b0000000-0000-0000-0000-000000000010',(select id from public.sales_orders),'2026-01-01',1,'')$$,'P0001','insufficient finished stock','cannot deliver nonexistent stock');
select throws_ok($$select public.set_sales_order_status((select id from public.sales_orders),'entregado')$$,'P0001','invalid status','cannot mark delivered manually');
select throws_ok($$delete from public.order_deliveries$$,'42501',null,'direct history deletion denied');
select * from finish();
rollback;
